      <tr><td>4</td><td>Alan Menken</td><td>3</td><td>1989, 1991, 1992</td></tr>
      <tr><td>8</td><td>Mikl&oacute;s R&oacute;zsa</td><td>2</td><td>1946, 1959</td></tr>
